/// Generate a [`Fix`] to remove an unnecessary dictionary spread.
fn unnecessary_spread_fix(
    dict: &ast::ExprDict,
    prev_end: TextSize,
    locator: &Locator,
) -> Option<Fix> {
    // Find the `**` token preceding the spread.
    let doublestar = SimpleTokenizer::starts_at(prev_end, locator.contents())
        .find(|tok| matches!(tok.kind(), SimpleTokenKind::DoubleStar))?;

    let mut edits = vec![];

    // Delete the `**` token, any parentheses wrapping the dictionary, and the
    // dictionary's opening brace.
    //
    // Ex) `**{a: 1, b: 2}` or `**({a: 1, b: 2})`
    for tok in SimpleTokenizer::starts_at(doublestar.start(), locator.contents()).skip_trivia() {
        match tok.kind() {
            SimpleTokenKind::DoubleStar | SimpleTokenKind::LParen => {
                edits.push(Edit::range_deletion(tok.range()));
            }
            SimpleTokenKind::LBrace if tok.start() == dict.start() => {
                edits.push(Edit::range_deletion(tok.range()));
                break;
            }
            _ => return None,
        }
    }

    if let Some(last) = dict.iter_values().last() {
        // Delete the dictionary's trailing comma and closing brace, as well as
        // any parentheses wrapping the dictionary.
        let mut closed = false;
        for tok in SimpleTokenizer::starts_at(last.end(), locator.contents()).skip_trivia() {
            match tok.kind() {
                SimpleTokenKind::Comma if !closed => {
                    edits.push(Edit::range_deletion(tok.range()));
                }
                SimpleTokenKind::RBrace if !closed => {
                    edits.push(Edit::range_deletion(tok.range()));
                    closed = true;
                }
                SimpleTokenKind::RParen if closed => {
                    edits.push(Edit::range_deletion(tok.range()));
                }
                _ => break,
            }
        }
    } else {
        // Ex) `**{}` or `**({})`
        for tok in SimpleTokenizer::starts_at(dict.end() - TextSize::of("}"), locator.contents())
            .skip_trivia()
        {
            match tok.kind() {
                SimpleTokenKind::RBrace if tok.start() == dict.end() - TextSize::of("}") => {
                    edits.push(Edit::range_deletion(tok.range()));
                }
                SimpleTokenKind::RParen => {
                    edits.push(Edit::range_deletion(tok.range()));
                }
                _ => break,
            }
        }
    }

    if edits.is_empty() {
        return None;
    }

    Some(Fix::safe_edits(
        edits.remove(0),
        edits,
    ))
}

